import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Instant;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;

class OrderServiceTest {

    private final OrderService service = new OrderService(new OrderRepository());

    @Test
    void placedOnCountsByWarsawDay() {
        // 1 Oct 2026 is in CEST (UTC+2): Warsaw day 1 Oct spans 30 Sep 22:00Z to 1 Oct 22:00Z.
        service.place("c-1", Money.pln(100), Instant.parse("2026-09-30T21:59:59Z")); // 30 Sep 23:59:59 Warsaw
        service.place("c-2", Money.pln(100), Instant.parse("2026-09-30T22:00:00Z")); // 1 Oct 00:00 Warsaw
        service.place("c-3", Money.pln(100), Instant.parse("2026-10-01T10:00:00Z")); // 1 Oct 12:00 Warsaw
        service.place("c-4", Money.pln(100), Instant.parse("2026-10-01T21:59:59Z")); // 1 Oct 23:59:59 Warsaw
        service.place("c-5", Money.pln(100), Instant.parse("2026-10-01T22:00:00Z")); // 2 Oct 00:00 Warsaw

        assertEquals(3, service.placedOn(LocalDate.of(2026, 10, 1)));
        assertEquals(1, service.placedOn(LocalDate.of(2026, 9, 30)));
        assertEquals(1, service.placedOn(LocalDate.of(2026, 10, 2)));
        assertEquals(0, service.placedOn(LocalDate.of(2026, 10, 3)));
    }
}
}
